import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-09-29","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-09-29","date":"2021-09-29T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","日志处理","缓存管理","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-09-29.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-09-29.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-09-29.md"};function o(s,e,n,h,c,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>pin crash问题修复</strong>：上周已推送补丁修复了pin crash问题，并由父级处理。</li><li><strong>weight hard limits crash和segment cleaner问题处理</strong>：将推送PR解决这些问题，关键在于执行out-of-line segment writes前检查segment cleaner的full status，并允许多个out-of-line segment writes。</li><li><strong>缓存LRU优化</strong>：计划优化缓存LRU，实现更有意义的recaching。</li><li><strong>日志批处理优化</strong>：正在研究日志批处理，已验证可以将写回列表放入队列并合并到更大的缓冲区列表中，然后调用正确的缓冲区。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>日志批处理策略</strong>：讨论了使用定时器或阈值触发大缓冲区写入磁盘的策略，建议不使用定时器或阈值，在没有写入操作时立即写入缓冲区中的数据。</li><li><strong>日志批处理实现细节</strong>：讨论了缓冲区交换和写入操作的处理，以及如何避免在段滚动时写过段末尾的问题。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>日志批处理策略</strong>：决定不使用定时器或阈值，在没有写入操作时立即写入缓冲区中的数据。</li><li><strong>日志批处理实现</strong>：决定在写入操作完成时，立即将缓冲区中的数据写入磁盘，并在段滚动时确保不写过段末尾。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>推送PR</strong>：推送解决weight hard limits crash和segment cleaner问题的PR。</li><li><strong>优化缓存LRU</strong>：继续优化缓存LRU，实现更有意义的recaching。</li><li><strong>日志批处理优化</strong>：继续研究日志批处理，确保实现细节符合讨论的策略。</li><li><strong>实现集群日志</strong>：正在实现集群日志功能，并准备提交一个draft PR。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>代码审查</strong>：承诺尽快完成对其他PR的审查。</li><li><strong>多设备支持PR修改</strong>：根据建议修改了多设备支持PR，并实现了PC和距离放置策略。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议结束时，大家互相道别，祝愿对方有美好的一天或晚上。</li></ul><h3 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h3><ul><li>pin crash</li><li>weight hard limits crash</li><li>segment cleaner</li><li>out-of-line segment writes</li><li>cache LRU</li><li>journal batching</li><li>file store journal</li><li>segment roll</li><li>multi-device support PR</li><li>PC and distance placement strategy</li><li>cluster log</li></ul>',15)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
